%  Constrained damping layer for B6clearclfE1=2.1e11;E2=1e9;eta=0.2;E2c=E2*(1+i*eta);G2=E2/3;etag=0.2;G2c=G2*(1+i*etag);E3=E1;h1=5e-3;h2=5e-3;%1e-5:1e-4:h1;h3=0.5e-3;L=1.0;for modeno=5;  p=modeno*pi/L;  g=G2c./(E3*h3*h2*p^2);  h21=(h1+h2)/2;  h31=(h1+h3)/2+h2;  D=(E2c*h2.*(h21-h31/2)+g.*(E2c*h2.*h21+E3*h3.*h31))./...    (E1*h1+E2c*h2/2+g.*(E1*h1+E2c*h2+E3*h3));  EI=E1*h1.^3/12+E2c*h2.^3/12+E3*h3.^3/12-E2c*h2.^2/12.*(h31-D)./(1+g)+...     E1*h1.*D.^2+E2c*h2.*(h21-D).^2+E3*h3.*(h31-D).^2-...     (E2c*h2/2.*(h21-D)+E3*h3.*(h31-D)).*(h31-D)./(1+g);  %  Now corresponding free layer  erat=E2c/E1;  hrat=h2/h1;  EIratio=1+erat*hrat.^3+3*(1+hrat).^2*erat.*hrat./(1+erat*hrat);  plot(h2*1000,imag(EI)./real(EI),'-k',h2*1000,imag(EIratio)./real(EIratio),'--k')  hold onendxlabel('Thickness of damping layer (mm)');ylabel('Effective eta');